(() => {
'use strict';
const E=window.BudgetEngine, M=window.BudgetMonths, KEY='marge.budget.v1', $=s=>document.querySelector(s), clone=x=>JSON.parse(JSON.stringify(x));
const fmt=new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:2});
const eur=n=>fmt.format(Number.isFinite(n)?n:0), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>{const s=String(v).trim().replace(/\s/g,'').replace(',','.');return s!==''&&/^-?\d+(\.\d+)?$/.test(s)?Number(s):NaN};
const uid=()=>globalThis.crypto?.randomUUID?.()||`b${Date.now()}${Math.random().toString(16).slice(2)}`;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`};
const moveMonth=(k,delta)=>{const [y,m]=k.split('-').map(Number),d=new Date(y,m-1+delta,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`};
const monthName=k=>new Date(`${k}-15T12:00:00`).toLocaleDateString('fr-FR',{month:'long',year:'numeric'});
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',sliders:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',chevron:'<path d="m9 5 7 7-7 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',up:'<path d="M7 17 17 7M7 7h10v10"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 2-1 3 2 3h3l2 3 3-1 1-3 3-1 2-3-2-2 1-3-2-3h-3l-2-3z"/>',shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',leaf:'<path d="M20 3C10 2 3 6 4 13c0 5 5 7 9 5 6-3 6-10 7-15Z"/><path d="M3 21 14 10"/>',bank:'<path d="m3 8 9-5 9 5M3 9h18M5 10v8m7-8v8m7-8v8M3 21h18"/>',trophy:'<path d="M8 3h8v6a4 4 0 0 1-8 0zM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 1v6m-4 2h8"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v5l3 2"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14z"/>',wallet:'<rect x="3" y="6" width="18" height="15" rx="3"/><path d="M3 8V5l14-3v4m-1 6h5v5h-5z"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const rules=()=>({threshold:500,savingPct:80,rPct:70,caPct:0,tPct:30});
const blankBudget=()=>[['ca','Logement','Fixes'],['ca','Assurances','Administratif'],['ca','Santé','Santé'],['ca','Autres charges','Fixes'],['r','Abonnements','Abonnements'],['r','Courses & repas','Repas'],['r','Loisirs & sorties','Loisirs'],['r','Imprévus','Imprévus']].map(([account,name,category])=>({id:uid(),account,name,category,amount:0,enabled:true}));
const fresh=()=>({version:1,selectedMonth:today(),settings:{goal:1500,theme:'light'},plans:[{from:'1900-01',budget:blankBudget(),rules:rules()}],months:{},achievements:{},lastExport:null});
let persistent=fresh(),loadError=false,saveFailed=false,storageConflict=false;
try{const raw=localStorage.getItem(KEY);if(raw){const loaded=JSON.parse(raw);validateState(loaded);persistent=loaded;}}catch(e){loadError=true;}
let state=persistent,demo=false,page='overview',budgetAccount='ca',draft=null,dirty=false,activeForm=null,toastTimer;
const app=$('#app'),dialog=$('#dialog');
function syncPWA(){window.MargePWA?.setBusy(dirty||dialog.open||saveFailed||storageConflict||loadError);}
function pwaStatusText(){const s=window.MargePWA?.getStatus();if(!s)return 'Ouvre la version hébergée pour installer Marge.';if(s.error)return s.error;if(s.updateAvailable)return 'Mise à jour prête : elle s’appliquera après fermeture des fenêtres et enregistrement des saisies.';if(s.offlineReady)return 'Disponible hors connexion. Les mises à jour sont vérifiées automatiquement.';return s.supported?'Préparation du mode hors connexion…':'L’installation nécessite la version HTTPS et un navigateur compatible.';}
function refreshPWAStatus(){const el=dialog.querySelector('[data-pwa-status]');if(el)el.textContent=pwaStatusText();}
async function installApp(){const result=await window.MargePWA?.install();if(!result)return;switch(result.outcome){case'instructions':openDialog('Installer Marge',`<p class="dialog-intro">${esc(result.instructions)}</p><p class="help">Ouvre Marge une première fois en ligne. Ensuite, ton budget reste accessible hors connexion. Les données restent sur cet appareil.</p>`);break;case'accepted':toast('Installation demandée. Termine la validation du navigateur.');break;case'already-installed':toast('Marge est déjà ouverte en tant qu’application.');break;}}
function writesBlocked(allowRecovery=false){if(demo)return false;if(storageConflict){toast('Un autre onglet a modifié les données. Recharge cette page avant de les modifier.',true);return true;}if(loadError&&!allowRecovery){toast('Exporte la sauvegarde illisible depuis les paramètres, puis importe une sauvegarde ou réinitialise l’application.',true);return true;}return false;}
function persist(){if(demo)return true;if(writesBlocked())return false;try{localStorage.setItem(KEY,JSON.stringify(state));persistent=state;saveFailed=false;return true;}catch(e){saveFailed=true;toast('Sauvegarde impossible sur cet appareil. Tes modifications restent dans cette page : exporte-les pour les conserver.',true);return false;}finally{syncPWA();}}
function toast(msg,error=false){if(saveFailed&&!error)return;const t=$('#toast');t.textContent=msg;t.className=`toast${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.add('hidden'),5500);}
function defaultsFor(k){return [...state.plans].filter(p=>p.from<=k).sort((a,b)=>b.from.localeCompare(a.from))[0]||state.plans[0];}
function getMonth(k=state.selectedMonth){return M.getMonth(state,k);}
function carryReport(k=state.selectedMonth){return M.reportFor(state,k);}
function reportSummary(m){
  const r=carryReport(m.key);if(!r)return '';
  return `<div class="carry-summary"><div><strong>Reports de ${esc(monthName(r.sourceKey))}</strong><span class="report-status">${r.provisional?'Prévisionnels':'Soldes réels'}</span></div><p>Tampon <strong>${eur(r.bufferTotal)}</strong> · Livret A <strong>${eur(r.savingsOpening)}</strong></p><small>${r.provisional?'Le mois précédent n’est pas clôturé. Les soldes réels remplaceront ces prévisions.':'Les soldes de clôture sont repris, sans ajouter à nouveau le tampon.'}${r.skipped?' Aucun mouvement n’est supposé pendant les mois non renseignés.':''}</small></div>`;
}
function carryDescription(m){
  const r=carryReport(m.key);if(!r||m.closed)return '';
  const items=[];if(m.carry?.buffer)items.push('Tampon');if(m.carry?.savings)items.push('Livret A');
  return `<div class="carry-strip"><span>${items.length?`${items.join(' et ')} repris de ${esc(monthName(r.sourceKey))}${r.provisional?' · prévisionnel':''}`:'Soldes de départ saisis manuellement'}</span><button class="inline-link" data-action="prepare">${items.length?'Ajuster':'Activer les reports'} ${icon('edit')}</button></div>`;
}
const current=()=>getMonth();
function commitMonth(m){if(writesBlocked())return false;m.key=state.selectedMonth;state.months[m.key]=m;award();return persist();}
function stats(){const ms=Object.values(state.months);const closed=ms.filter(m=>m.closed);const prepared=ms.filter(m=>m.prepared&&!m.forecast);const xp=prepared.length*30+closed.length*70+(state.achievements.goal?100:0);return {closed,prepared,xp,level:Math.floor(xp/150)+1,progress:xp%150};}
function award(){const {closed,prepared}=stats();if(prepared.length)state.achievements.first=true;if(closed.length)state.achievements.closed=true;if(closed.length>=3)state.achievements.regular=true;if(Object.values(state.months).some(m=>m.closed&&m.closing.closingCA+m.closing.closingR>=state.settings.goal&&state.settings.goal>0))state.achievements.goal=true;}
function calc(m=current()){return E.calculate(m);}
function operation(m,id,c=calc(m)){const target=id==='r'?c.transferR:c.savingsAdd;const paid=m.executed?.[id]||0;const remaining=Math.round((target-paid)*100)/100;return {target,paid,remaining,complete:remaining===0};}
function operationRow(m,id,c){const o=operation(m,id,c),direction=o.complete?o.paid:o.remaining;const title=id==='r'?(direction>=0?'Verser sur Revolut':'Rapatrier sur CA'):(direction>=0?'Mettre de côté':'Ajuster depuis le Livret A');const route=id==='r'?(direction>=0?'CA → Revolut':'Revolut → CA'):(direction>=0?'CA → Livret A':'Livret A → CA');const sub=o.complete&&o.paid!==0?'Effectué · '+route:o.paid!==0?'Ajustement restant · '+route:route;return actionRow(id,Math.abs(o.complete?o.paid:o.remaining),title,sub,o.complete,m.closed||(o.complete&&o.paid===0));}

function openDialog(title,body,footer='',form=null){dialog.innerHTML=`<div class="dialog-header"><div><span class="eyebrow">MARGE · MON BUDGET</span><h2>${title}</h2></div><button class="icon-btn close-btn" data-action="close-dialog" aria-label="Fermer">${icon('close')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;activeForm=form;if(!dialog.open)dialog.showModal();syncPWA();}
function errorBox(text){const el=dialog.querySelector('.form-error');if(el){el.textContent=text;el.classList.remove('hidden');el.scrollIntoView({block:'nearest'});}else toast(text,true);}
function numberField(name,label,value,help='',options={}){return `<label class="field" for="${name}"><span>${label}</span><div class="input-unit ${options.moneyClass?'money-input':''}"><input id="${name}" name="${name}" type="text" inputmode="decimal" autocomplete="off" value="${esc(value)}" ${options.required===false?'':'required'} ${options.disabled?'disabled':''} aria-describedby="${name}-help"><span>${options.unit||'€'}</span></div><small class="help" id="${name}-help">${help}</small></label>`;}
function fieldValue(name){return num(dialog.querySelector(`[name="${name}"]`)?.value);}
function banner(){if(demo)return `<div class="banner demo"><span>${icon('spark')} Mode démonstration · données fictives</span><button class="btn small secondary" data-action="exit-demo">Utiliser mes données</button></div>`;if(loadError)return `<div class="banner warning">La sauvegarde précédente n’a pas pu être lue. Elle n’a pas été écrasée. Exporte-la depuis les paramètres avant de recommencer.</div>`;if(storageConflict)return `<div class="banner warning" role="alert">Les données ont changé dans un autre onglet. Cette page est en lecture seule : recharge-la avant de continuer. Tu peux exporter les montants actuellement affichés.</div>`;if(saveFailed)return `<div class="banner warning" role="alert">Tes dernières modifications ne sont pas sauvegardées. Elles restent dans cette page : exporte une sauvegarde avant de la fermer.</div>`;return '';}
function render(){
  document.body.dataset.theme=state.settings.theme;
  const m=current(),c=calc(m),s=stats();
  const label=m.closed?'Clôturé':m.forecast?'Prévision':!m.prepared?'À préparer':c.budgetTotal===0&&!m.budgetConfirmed?'Budget à compléter':!c.funded?'À équilibrer':'En cours';
  app.innerHTML=`<div class="app-shell"><header class="app-header"><div class="header-inner"><a class="wordmark" href="#" data-action="overview" aria-label="Marge, vue d'ensemble">marge<span>.</span></a><nav class="primary-nav" aria-label="Navigation principale"><button data-action="overview" class="${page==='overview'?'active':''}" ${page==='overview'?'aria-current="page"':''}>Vue d’ensemble</button><button data-action="budget" class="${page==='budget'?'active':''}" ${page==='budget'?'aria-current="page"':''}>Budget</button></nav><button class="icon-btn more-button" data-action="more" aria-label="Plus : historique, progrès et paramètres"><span aria-hidden="true">···</span></button></div></header><main class="main ${page==='forecast'?'main-forecast':''}">${banner()}<header class="page-heading"><div><div class="month-context"><span class="year-label">${page==='forecast'?'LES PROCHAINS MOIS':m.key.slice(0,4)}</span><span class="status ${m.closed?'closed':c.funded&&m.prepared?'ready':''}">${page==='forecast'?'Estimation':label}</span></div><div class="heading-line"><h1>${page==='overview'?`<button class="month-title" data-action="choose-month" aria-label="Choisir le mois : ${esc(monthName(m.key))}">${esc(monthName(m.key).replace(/ \d{4}$/,''))}<span class="heading-dot">.</span></button>`:page==='forecast'?'La suite<span class="heading-dot">.</span>':'Le budget<span class="heading-dot">.</span>'}</h1><div class="month-arrows">${page==='budget'?`<button class="compact-month" data-action="choose-month">${esc(monthName(m.key))}</button>`:''}<button class="icon-btn" data-action="prev-month" aria-label="Mois précédent"><span class="rotate">${icon('chevron')}</span></button><button class="icon-btn" data-action="next-month" aria-label="Mois suivant">${icon('chevron')}</button></div></div></div>${m.prepared&&page==='overview'?`<button class="income-link" data-action="${m.closed?'show-closing':'prepare'}"><span>${m.closed?'Mois clôturé':m.forecast?'Revenu estimé':'Revenu net'}</span><strong>${eur(m.salary)}</strong>${icon(m.closed?'history':'edit')}</button>`:''}</header>${page==='overview'?overview(m,s):page==='forecast'?forecastView():budgetView(m)}<footer class="page-footer"><span>Un peu plus de liberté.</span><button data-action="history">Historique ${icon('arrow')}</button></footer></main></div>`;
  syncPWA();
}
function heroMoney(value){return new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(value);}
// Checkpoints: balances only; movements are frozen separately to preserve past readings.
function checkpointDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function checkpointEligible(m){const c=calc(m);return m.prepared&&!m.closed&&!m.forecast&&m.key===today()&&c.valid&&(c.budgetTotal>0||m.budgetConfirmed===true);}
function checkpointReason(m){return m.closed?'Le mois est clôturé.':m.key!==today()?'Les relevés se font pendant le mois en cours.':m.forecast?'Confirme le salaire reçu avant de faire le point.':'Prépare le mois et valide le budget avant de faire le point.';}
function checkpointDialog(){
  const m=current();if(!checkpointEligible(m))return toast(checkpointReason(m),true);
  if(writesBlocked())return;
  const tracking=E.checkpointTracking(m,new Date()),last=tracking.latest;
  openDialog('Faire le point',`<p class="dialog-intro">${esc(monthName(m.key))} · Saisis les soldes affichés par tes banques, tampon compris.</p><form id="checkpoint-form"><div class="fields-grid">${numberField('checkpointCA','Solde actuel du CA',last?last.balanceCA:m.openingCA,last?'Dernier relevé : à actualiser.':'Solde d’ouverture : à actualiser.',{moneyClass:true})}${numberField('checkpointR','Solde actuel de Revolut',last?last.balanceR:m.openingR,last?'Dernier relevé : à actualiser.':'Solde d’ouverture : à actualiser.',{moneyClass:true})}</div><p class="help">Pointe d’abord les virements réellement effectués dans « À faire ». Ils seront exclus des dépenses. Le salaire renseigné doit avoir été reçu.</p><p class="help">Un nouveau point aujourd’hui remplace celui du même jour. Les autres relevés sont conservés.</p><div class="form-error banner warning hidden" role="alert"></div></form>`,`<button class="btn secondary" data-action="close-dialog">Annuler</button><button class="btn primary" data-action="save-checkpoint">Enregistrer le point ${icon('check')}</button>`,'checkpoint');
}
function saveCheckpoint(){
  if(writesBlocked())return;
  const m=current();if(!checkpointEligible(m))return errorBox(checkpointReason(m));
  const date=checkpointDate(),point={date,balanceCA:fieldValue('checkpointCA'),balanceR:fieldValue('checkpointR')};
  const checkpoints=[...(m.checkpoints||[]).filter(p=>p.date.slice(0,10)!==date),point].sort((a,b)=>a.date.localeCompare(b.date));
  const checkpointTransfers={...m.checkpointTransfers};
  for(const old of m.checkpoints||[])if(old.date.slice(0,10)===date)delete checkpointTransfers[old.date];
  checkpointTransfers[date]={r:m.executed?.r||0,savings:m.executed?.savings||0};
  const candidate={...m,checkpoints,checkpointTransfers};
  const errors=E.validateCheckpoints(candidate);if(errors.length)return errorBox(errors.join(' '));
  if(!commitMonth(candidate)){render();return errorBox('Ce point n’est pas sauvegardé. Exporte les données avant de fermer la page.');}
  dialog.close();render();toast('Point enregistré. Tes jauges sont à jour.');
}
function checkpointGauge(id,name,m,tracking){
  const a=tracking.accounts?.[id],time=tracking.elapsedPct,pct=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(n),hasPoint=!!tracking.latest;
  if(!tracking.valid)return `<p class="checkpoint-empty">${esc(tracking.errors.join(' '))}</p>`;
  const ahead=hasPoint&&a.spentPct!==null&&a.spentPct>time;
  const consumed=hasPoint?(a.spent<0?`Entrées nettes : ${eur(-a.spent)}`:`Consommé : ${eur(a.spent)}`):'Aucun relevé pour le moment';
  const amount=hasPoint?(a.spentPct===null?'Sans budget':`${pct(Math.max(0,a.spentPct))} %`):'—';
  const valueText=hasPoint?`${consumed}. ${a.spentPct===null?'Aucun budget alloué.':`${pct(Math.max(0,a.spentPct))} % du budget consommé.`} ${pct(time)} % du mois écoulé.`:'';
  const date=hasPoint?new Date(`${tracking.latest.date.slice(0,10)}T12:00:00`).toLocaleDateString('fr-FR',{day:'numeric',month:'long'}):'';
  return `<div class="checkpoint-tracking ${ahead?'is-ahead':''}"><div class="pacing-meta"><span>${consumed}</span><strong>${amount}</strong></div><div class="pacing-track" ${hasPoint?`role="progressbar" aria-label="Budget consommé ${name}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${a.barPct}" aria-valuetext="${esc(valueText)}"`:''}><span class="pacing-fill" style="width:${hasPoint?a.barPct:0}%"></span><span class="pacing-marker" style="left:${time}%" aria-hidden="true"></span></div><p class="pacing-caption"><span>${hasPoint?`Relevé du ${esc(date)}`:'Fais le point pour voir ta consommation.'}</span><span>Trait : ${pct(time)} % du mois écoulé</span></p>${hasPoint&&a.spent<0?'<p class="pacing-warning">Des entrées ou remboursements dépassent les dépenses. Vérifie aussi le pointage des virements.</p>':hasPoint&&a.spentPct===null&&a.spent>0?'<p class="pacing-warning">Dépenses constatées sans budget alloué à ce compte.</p>':ahead?`<p class="pacing-warning">${a.spentPct>100?'Budget dépassé.':'Consommation en avance sur le mois.'}</p>`:''}</div>`;
}

function overview(m,s){
  const tracking=E.checkpointTracking(m,new Date());
  const c=calc(m),ready=m.prepared&&c.valid&&(c.budgetTotal>0||m.budgetConfirmed===true);
  const buffer=m.closed?m.closing.closingCA+m.closing.closingR:(ready?c.bufferEndPlan:0);
  const savings=m.closed?m.closing.savingsActual:(ready?c.savingsProjected:m.savingsOpening);
  const pct=state.settings.goal>0?Math.min(100,Math.max(0,buffer/state.settings.goal*100)):0;
  if(!m.prepared){
    const hasBudget=c.budgetTotal>0||m.budgetConfirmed;
    return `<section class="first-month"><div class="first-copy"><span class="section-kicker">${hasBudget?'IL RESTE UNE ÉTAPE':'POUR COMMENCER'}</span><h2>${hasBudget?'Le budget est posé.<br>Place à ton mois.':'Plus de marge.<br>Moins de calculs.'}</h2><p>${hasBudget?`${eur(c.budgetTotal)} de dépenses prévues. Ajoute ton salaire et tes soldes de départ pour voir la répartition.`:'Tes deux comptes, ton épargne et tes projets.<br>Tout commence par un budget qui te ressemble.'}</p><div class="first-actions"><button class="btn primary" data-action="${hasBudget?'prepare':'budget'}">${hasBudget?'Préparer mon mois':'Définir mon budget'} ${icon('arrow')}</button>${!demo?'<button class="btn text-btn" data-action="demo">Voir un exemple</button>':''}</div>${reportSummary(m)}</div><div class="start-steps"><div><span class="step-index">01</span><p><strong>Ton budget</strong><span>Les dépenses prévues sur CA et Revolut.</span></p>${hasBudget?icon('check'):''}</div><div><span class="step-index">02</span><p><strong>Ta répartition</strong><span>Le salaire, le Livret A et le tampon.</span></p></div></div></section>`;
  }
  return `${!ready&&!m.closed?`<div class="banner warning"><div><strong>Complète ton budget pour finaliser le mois.</strong><p>Les virements apparaîtront après validation de tes dépenses.</p></div><button class="btn secondary small" data-action="budget">Définir mes dépenses ${icon('arrow')}</button></div>`:''}
  ${ready&&!c.funded&&!m.closed?`<div class="banner warning"><div><strong>Il reste ${eur(c.shortfall)} à financer.</strong><p>${c.bufferAvailable>0&&!m.useBuffer?`${eur(Math.min(c.deficit,c.bufferAvailable))} peuvent être pris sur le tampon.`:'Ajuste les dépenses prévues pour équilibrer le mois.'}</p></div><div class="banner-actions">${!m.useBuffer&&c.bufferAvailable>0?'<button class="btn secondary small" data-action="use-buffer">Utiliser le tampon</button>':''}<button class="btn primary small" data-action="budget">Ajuster le budget</button></div></div>`:''}
  ${ready&&c.bufferUsed>0&&!m.closed?`<div class="inline-notice"><span>${eur(c.bufferUsed)} du tampon financent ce mois.</span><button data-action="cancel-buffer">Annuler ce choix</button></div>`:''}
  ${m.salaryReference?`<p class="salary-reference">${m.forecast?'Estimation':'Référence'} : paie de ${esc(monthName(m.salaryReference.sourcePayroll))} · ${eur(m.salaryReference.salary)} net payé.</p>`:''}
  ${carryDescription(m)}
  <section class="month-body"><div class="spending-focus"><div class="section-label checkpoint-heading"><h2>Mes comptes ce mois-ci</h2><button class="btn small secondary" data-action="checkpoint" ${checkpointEligible(m)?'':`disabled title="${esc(checkpointReason(m))}"`}>Faire le point ${icon('plus')}</button></div><p class="section-kicker">${m.closed?'Budget prévu':ready&&c.funded?'Budget utilisable':'Budget à finaliser'}</p><div class="hero-amount">${ready?heroMoney(c.availableCA+c.availableR):'—'}<span>€</span></div><div class="account-ledger">${[['ca','Crédit Agricole',c.availableCA,c.caBonus],['r','Revolut',c.availableR,c.rBonus]].map(([id,name,total,bonus])=>`<article class="account-card ${id}"><div class="account-card-head"><div><i class="account-dot ${id}"></i><span>${name}</span>${ready&&bonus>0?`<small>dont ${eur(bonus)} de surplus</small>`:''}</div><strong class="account-balance">${ready?eur(total):'—'}</strong></div>${checkpointGauge(id,name,m,tracking)}</article>`).join('')}</div><p class="checkpoint-note">${tracking.transferSnapshotSource==='executed-fallback'?'Ce relevé importé utilise les virements actuellement pointés. Refais le point pour figer cette référence. ':''}${m.key!==today()?'Les points se saisissent pendant le mois en cours. ':''}Le rythme est indicatif : les charges fixes peuvent tomber en début de mois. Les remboursements réduisent le consommé.</p><button class="inline-link" data-action="budget">Ajuster les enveloppes ${icon('arrow')}</button></div>
  <div class="next-actions"><div class="section-label"><h2>${m.closed?'Les virements':'À faire'}</h2><span>${ready&&c.funded?`${Number(operation(m,'r',c).complete)+Number(operation(m,'savings',c).complete)} / 2 effectués`:'Après répartition'}</span></div>${ready&&c.funded?`<div class="action-list">${operationRow(m,'r',c)}${operationRow(m,'savings',c)}</div><p class="action-footnote">${c.tamponBonus>0?`${eur(c.tamponBonus)} sont réservés au tampon sur CA.`:'Le tampon reste réservé sur CA.'}</p>`:`<div class="actions-unavailable"><p>${ready?'Équilibre le budget pour connaître les montants à virer.':'Renseigne les dépenses prévues pour calculer tes virements.'}</p><button class="inline-link" data-action="budget">Ouvrir le budget ${icon('arrow')}</button></div>`}</div></section>
  <section class="reserves" aria-label="Mes réserves"><div class="reserve-block buffer-block"><div class="section-label"><h2>Le tampon</h2><button class="goal-edit" data-action="goal" aria-label="Modifier l’objectif tampon">Objectif ${eur(state.settings.goal)} ${icon('edit')}</button></div><div class="reserve-amount">${heroMoney(buffer)}<span>€</span></div><div class="reserve-meta"><span>${m.closed?'Solde réel en fin de mois':'Après répartition'}</span><strong>${Math.round(pct)} % de l’objectif</strong></div><div class="progress" role="progressbar" aria-label="Objectif tampon" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(pct)}"><div class="progress-fill" style="width:${pct}%"></div></div><p class="reserve-note">${m.closed?`${eur(buffer-c.openingTotal)} d’évolution sur le mois.`:c.bufferUsed>0?`${eur(c.bufferUsed)} utilisés pour compléter le budget.`:`+ ${eur(ready?c.tamponBonus:0)} réservés ce mois-ci.`}</p></div><div class="reserve-block savings-block"><div class="section-label"><h2>Le Livret A</h2><span>Crédit Agricole</span></div><div class="reserve-amount">${heroMoney(savings)}<span>€</span></div><div class="reserve-meta"><span>${m.closed?'Solde réel en fin de mois':'Après versement prévu'}</span><strong>+ ${eur(ready?c.savingsAdd:0)}</strong></div><div class="savings-caption">${m.closed?'L’épargne réellement mise de côté.':'Ton épargne, séparée de l’argent du mois.'}</div></div></section>
  <details class="calculation-details"><summary><span>Le détail de la répartition</span>${icon('plus')}</summary><div class="calculation-body"><div class="details-table">${detailRow('Soldes de départ CA + Revolut, avant salaire',c.openingTotal)}${detailRow('Salaire net',m.salary)}${detailRow('Budget Crédit Agricole',c.budgetCA)}${detailRow('Budget Revolut',c.budgetR)}${detailRow('Reste hors budget',c.remainder)}${c.openingTotal<0?detailRow('Découvert de départ à couvrir',-c.openingTotal):''}${detailRow('Livret A reporté au début du mois',m.savingsOpening)}${detailRow('Vers le Livret A',c.savingsAdd)}${detailRow('Surplus à répartir',c.surplus)}${detailRow('Supplément Revolut',c.rBonus)}${detailRow('Supplément CA',c.caBonus)}${detailRow('Ajout au tampon',c.tamponBonus)}</div><p class="help">À partir de ${eur(m.rules.threshold)} de reste finançable : ${m.rules.savingPct} % vers le Livret A, ${round(100-m.rules.savingPct)} % de surplus. En dessous : tout vers le Livret A. Le tampon précédent est déjà inclus dans les soldes de départ.</p></div></details>
  <div class="month-end"><span>${m.closed?'Les soldes réels de ce mois sont enregistrés.':'Quand le mois est terminé, fais le point sur tes soldes.'}</span><button class="btn secondary" data-action="${m.closed?'show-closing':'close-month'}" ${!m.closed&&(!c.funded||!ready)?'disabled':''}>${m.closed?'Voir le bilan':'Clôturer le mois'} ${icon('arrow')}</button></div>`;
}
const round=n=>Math.round(n*100)/100;
const detailRow=(label,value)=>`<div><span>${label}</span><strong>${eur(value)}</strong></div>`;
function actionRow(id,amount,title,sub,done,closed){return `<div class="action-row"><button class="check-btn ${done?'checked':''}" data-action="toggle-done" data-id="${id}" role="checkbox" aria-checked="${!!done}" aria-label="${esc(title)} : effectué" ${closed?'disabled':''}>${done?icon('check'):''}</button><div class="action-copy"><strong>${title}</strong><span>${amount===0?'Aucun virement nécessaire':sub}</span></div><strong class="action-amount">${eur(amount)}</strong></div>`;}
function levelName(n){return ['Premier cap','Bon rythme','Cap maintenu','Esprit tranquille','Belle autonomie'][Math.min(4,n-1)];}
function ensureDraft(m){if(!draft||draft.key!==m.key)draft={key:m.key,budget:clone(m.budget),rules:clone(m.rules)};}
function budgetView(m){ensureDraft(m);const totals={ca:0,r:0};draft.budget.forEach(b=>{if(b.enabled)totals[b.account]+=Number.isFinite(b.amount)?b.amount:0});const r=draft.rules;const mode=r.rPct===70&&r.caPct===0&&r.tPct===30?'buffer':r.rPct===60&&r.caPct===20&&r.tPct===20?'balance':r.rPct===90&&r.caPct===10&&r.tPct===0?'available':'custom';return `${m.closed?'<div class="banner success">'+icon('lock')+' Budget figé pour ce mois clôturé. Sélectionne un autre mois pour le modifier.</div>':''}<div class="budget-tabs"><button class="tab-btn ${budgetAccount==='ca'?'active':''}" data-action="budget-ca">Crédit Agricole <strong>${eur(totals.ca)}</strong></button><button class="tab-btn ${budgetAccount==='r'?'active':''}" data-action="budget-r">Revolut <strong>${eur(totals.r)}</strong></button></div><div class="budget-layout">${['ca','r'].map(a=>`<section class="card budget-panel ${a} ${budgetAccount===a?'mobile-selected':''}"><div class="card-header"><div class="card-title-icon"><span class="account-icon">${a==='ca'?icon('bank'):'R'}</span><div><h2>${a==='ca'?'Crédit Agricole':'Revolut'}</h2><p class="muted">${a==='ca'?'Fixes, administratif & santé':'Abonnements, repas & loisirs'}</p></div></div></div><div class="budget-total" id="total-${a}">${eur(totals[a])}<small>par mois</small></div><div class="budget-lines">${draft.budget.filter(b=>b.account===a).map(b=>`<div class="budget-row ${!b.enabled?'disabled-row':''}" data-row="${esc(b.id)}"><input type="checkbox" class="line-toggle" data-budget-id="${esc(b.id)}" data-prop="enabled" aria-label="Activer ${esc(b.name)}" ${b.enabled?'checked':''} ${m.closed?'disabled':''}><div class="budget-row-name"><input class="name-input" aria-label="Nom de la dépense" data-budget-id="${esc(b.id)}" data-prop="name" value="${esc(b.name)}" maxlength="80" placeholder="Nom de la dépense" ${m.closed?'disabled':''}></div><div class="money-input"><input type="text" inputmode="decimal" aria-label="Montant de ${esc(b.name)}" data-budget-id="${esc(b.id)}" data-prop="amount" value="${Number.isFinite(b.amount)?b.amount:''}" ${m.closed?'disabled':''}><span>€</span></div><button class="icon-btn small delete-line" data-action="remove-line" data-id="${esc(b.id)}" aria-label="Supprimer ${esc(b.name)}" ${m.closed?'disabled':''}>${icon('trash')}</button></div>`).join('')}</div><button class="btn add-line" data-action="add-line" data-account="${a}" ${m.closed?'disabled':''}>${icon('plus')} Ajouter une dépense</button></section>`).join('')}</div><details class="rules-fold"><summary><span>Répartition automatique</span><span class="rules-summary-value">${r.rPct} % R · ${r.caPct} % CA · ${r.tPct} % tampon ${icon('plus')}</span></summary><section class="card rules-card"><div class="card-header"><div><h2>Répartition automatique</h2><p class="muted">Le reste de ton salaire suit tes priorités.</p></div><span class="pill">PERSONNALISABLE</span></div><details open><summary class="rules-summary">1. Épargne & surplus</summary><div class="rules-grid"><label class="field"><span>Seuil de déclenchement</span><div class="input-unit"><input data-rule="threshold" type="text" inputmode="decimal" value="${r.threshold}" ${m.closed?'disabled':''}><span>€</span></div></label><label class="field"><span>Part vers le Livret A</span><div class="input-unit"><input data-rule="savingPct" type="text" inputmode="decimal" value="${r.savingPct}" ${m.closed?'disabled':''}><span>%</span></div></label><div class="field"><span>Surplus à répartir</span><strong class="derived-value" id="surplus-pct">${round(100-r.savingPct)} %</strong></div></div><p class="help">En dessous du seuil, tout le reste va au Livret A. À partir du seuil, ce partage s’applique à la totalité du reste finançable.</p></details><div class="rule-divider"></div><div class="rules-summary">2. Destination du surplus</div><div class="preset-grid">${[['buffer','Renforcer le tampon','70 % R · 30 % tampon'],['balance','Équilibrer','60 % R · 20 % CA · 20 % tampon'],['available','Priorité au disponible','90 % R · 10 % CA']].map(([id,t,desc])=>`<button class="preset ${mode===id?'active':''}" data-action="preset" data-id="${id}" ${m.closed?'disabled':''}><strong>${t}</strong><span>${desc}</span></button>`).join('')}</div><div class="rules-grid"><label class="field"><span>Revolut</span><div class="input-unit"><input data-rule="rPct" type="text" inputmode="decimal" value="${r.rPct}" ${m.closed?'disabled':''}><span>%</span></div></label><label class="field"><span>Crédit Agricole</span><div class="input-unit"><input data-rule="caPct" type="text" inputmode="decimal" value="${r.caPct}" ${m.closed?'disabled':''}><span>%</span></div></label><label class="field"><span>Tampon</span><div class="input-unit"><input data-rule="tPct" type="text" inputmode="decimal" value="${r.tPct}" ${m.closed?'disabled':''}><span>%</span></div></label></div><div id="rules-feedback" class="info-note">${icon('info')} Total : ${round(r.rPct+r.caPct+r.tPct)} %. Tu peux modifier chaque pourcentage.</div><div class="simulation-box" id="simulation">${budgetSimulation(m)}</div></section></details>${!m.closed?`<div class="budget-savebar"><div><strong id="draft-status">${dirty?'Modifications à enregistrer':'Budget mensuel'}</strong><span class="muted">Les mois clôturés restent inchangés.</span></div><select id="budget-scope" aria-label="Appliquer les changements"><option value="future">Ce mois et les suivants</option><option value="month">Ce mois uniquement</option></select><button class="btn primary" data-action="save-budget">Enregistrer ${icon('check')}</button></div>`:''}`;}
function budgetSimulation(m){const c=E.calculate({...m,budget:draft.budget,rules:draft.rules});if(c.valid===false||c.errors?.length)return `<span class="text-danger">${esc(c.errors.join(' '))}</span>`;if(!m.prepared)return 'Renseigne ton salaire dans la vue d’ensemble pour voir la répartition en euros.';return `Avec ton salaire de <strong>${eur(m.salary)}</strong> : <strong>${eur(c.savingsAdd)}</strong> vers le Livret A, <strong>${eur(c.rBonus)}</strong> de plus sur Revolut, <strong>${eur(c.caBonus)}</strong> sur CA et <strong>${eur(c.tamponBonus)}</strong> pour le tampon.${!c.funded?` <span class="text-danger">Il reste ${eur(c.shortfall)} à financer.</span>`:''}`;}
function refreshDraft(){dirty=true;syncPWA();const m=current();for(const a of ['ca','r']){const sum=draft.budget.filter(b=>b.account===a&&b.enabled).reduce((s,b)=>s+(Number.isFinite(b.amount)?b.amount:0),0);const el=$(`#total-${a}`);if(el)el.innerHTML=`${eur(sum)}<small>par mois</small>`;const tabTotal=app.querySelector(`[data-action="budget-${a}"] strong`);if(tabTotal)tabTotal.textContent=eur(sum);}const sp=$('#surplus-pct');if(sp)sp.textContent=`${round(100-draft.rules.savingPct)} %`;const feedback=$('#rules-feedback');if(feedback){const total=round(draft.rules.rPct+draft.rules.caPct+draft.rules.tPct);feedback.textContent=`Total : ${Number.isFinite(total)?total:'—'} %. ${total===100?'Répartition équilibrée.':'Le total doit être égal à 100 %.'}`;feedback.classList.toggle('text-danger',total!==100);}const sim=$('#simulation');if(sim)sim.innerHTML=budgetSimulation(m);const ds=$('#draft-status');if(ds)ds.textContent='Modifications à enregistrer';}
function saveBudget(){if(writesBlocked())return;const m=current();if(m.closed)return;const candidate={...m,budgetConfirmed:true,budget:clone(draft.budget),rules:clone(draft.rules),done:{r:false,savings:false}};if(candidate.budget.some(b=>!b.name.trim()))return toast('Donne un nom à chaque dépense.',true);const c=calc(candidate);if(c.valid===false||c.errors?.length)return toast(c.errors.join(' '),true);const scope=$('#budget-scope').value;if(scope==='future'){state.plans=state.plans.filter(p=>p.from<m.key);state.plans.push({from:m.key,confirmed:true,budget:clone(draft.budget),rules:clone(draft.rules)});for(const other of Object.values(state.months)){if(other.key>m.key&&!other.closed){other.budgetConfirmed=true;other.budget=clone(draft.budget);other.rules=clone(draft.rules);other.done={r:false,savings:false};}}}const saved=commitMonth(candidate);dirty=!saved;if(saved)draft=null;render();if(saved)toast('Budget enregistré. Ta répartition est à jour.');}
function prepare(){
  const m=current();if(m.closed)return;const r=carryReport(m.key),autoBuffer=!!(r&&m.carry?.buffer),autoSavings=!!(r&&m.carry?.savings);
  openDialog(m.prepared?'Ajuster mon mois':'Préparer mon mois',`<p class="dialog-intro">${esc(monthName(m.key))} · Le salaire arrive sur CA. Le tampon reste sur CA et l’épargne est sur ton Livret A.</p><form id="month-form"><div class="form-section"><h3>Mon revenu</h3>${numberField('salary','Salaire net du mois',m.salary)}</div>${reportSummary(m)}<div class="form-section"><h3>Mon tampon de départ</h3>${r?`<label class="checkbox-label carry-choice"><input type="checkbox" name="carryBuffer" ${autoBuffer?'checked':''}> Reporter automatiquement le tampon</label>`:''}<p class="help">Le tampon est déjà compris dans les soldes CA et Revolut. ${r?'Décoche le report pour saisir les soldes réellement constatés.':'Saisis les soldes du début de période avant la répartition, en déduisant les paiements en attente.'}</p><div class="fields-grid">${numberField('openingCA','Compte CA',m.openingCA,'',{disabled:autoBuffer})}${numberField('openingR','Compte Revolut',m.openingR,'',{disabled:autoBuffer})}</div><label class="checkbox-label"><input type="checkbox" name="salaryIncluded" ${m.salaryIncluded?'checked':''} ${autoBuffer?'disabled':''}> Le salaire de ce mois est déjà inclus dans le solde CA</label></div><div class="form-section"><h3>Mon Livret A de départ</h3>${r?`<label class="checkbox-label carry-choice"><input type="checkbox" name="carrySavings" ${autoSavings?'checked':''}> Reporter automatiquement le Livret A</label>`:''}${numberField('savingsOpening','Solde avant le versement du mois',m.savingsOpening,r?'Décoche le report pour ajuster un retrait, un versement ou des intérêts.':'Cette épargne est séparée du tampon.',{disabled:autoSavings})}</div><div class="form-error banner warning hidden" role="alert"></div><div class="info-note">${icon('info')} Les virements déjà pointés sont conservés : seule la différence reste à virer après une modification.</div></form>`,`<button class="btn secondary" data-action="close-dialog">Annuler</button><button class="btn primary" data-action="save-month">Calculer mon mois ${icon('arrow')}</button>`,'month');
}
function syncCarryFields(name){
  const r=carryReport();if(!r)return;
  if(name==='carryBuffer'){
    const enabled=dialog.querySelector('[name=carryBuffer]').checked;
    for(const key of ['openingCA','openingR']){const input=dialog.querySelector(`[name="${key}"]`);input.disabled=enabled;if(enabled)input.value=r[key];}
    const included=dialog.querySelector('[name=salaryIncluded]');included.disabled=enabled;if(enabled)included.checked=false;
  }
  if(name==='carrySavings'){
    const enabled=dialog.querySelector('[name=carrySavings]').checked,input=dialog.querySelector('[name=savingsOpening]');input.disabled=enabled;if(enabled)input.value=r.savingsOpening;
  }
}
function saveMonth(){
  if(writesBlocked())return;
  const old=current(),r=carryReport(),carry={buffer:!!(r&&dialog.querySelector('[name=carryBuffer]')?.checked),savings:!!(r&&dialog.querySelector('[name=carrySavings]')?.checked)};
  const m={...old,carry,salary:fieldValue('salary'),openingCA:carry.buffer?r.openingCA:fieldValue('openingCA'),openingR:carry.buffer?r.openingR:fieldValue('openingR'),salaryIncluded:carry.buffer?false:dialog.querySelector('[name=salaryIncluded]').checked,savingsOpening:carry.savings?r.savingsOpening:fieldValue('savingsOpening'),prepared:true,forecast:false,done:{r:false,savings:false}};
  const c=calc(m);if(c.valid===false||c.errors?.length)return errorBox(c.errors.join(' '));
  if(loadError)return errorBox('Exporte d’abord la sauvegarde illisible depuis les paramètres, puis réinitialise l’application.');
  const saved=commitMonth(m);if(!saved){render();return errorBox('Ces montants ne sont pas sauvegardés. Exporte les données avant de fermer la page.');}
  dialog.close();render();toast(c.budgetTotal===0?'Montants enregistrés. Complète maintenant tes dépenses dans Budget.':!c.funded?'Montants enregistrés. Il reste '+eur(c.shortfall)+' à financer.':'Ton mois est prêt. Chaque euro a sa place.');
}
function closeMonthDialog(){const m=current(),c=calc(m);if(m.closed||!m.prepared||!c.funded||(c.budgetTotal===0&&!m.budgetConfirmed))return;openDialog('Clôturer le mois',`<p class="dialog-intro">Saisis les soldes réels après tes dépenses, avant le salaire du mois suivant. Déduis les paiements en attente.</p><form><div class="fields-grid">${numberField('closingCA','Solde réel CA',0)}${numberField('closingR','Solde réel Revolut',0)}</div>${numberField('savingsActual','Solde réel du Livret A',c.savingsProjected,'Corrige ce montant si tu as effectué un retrait ou reçu des intérêts.')}<div class="info-note">${icon('shield')} Le nouveau tampon sera égal à CA + Revolut. La réserve précédente et les ${eur(c.tamponBonus)} déjà affectés ne seront pas ajoutés une seconde fois.</div><div class="close-preview" id="close-preview">Nouveau tampon : ${eur(0)}</div><label class="checkbox-label"><input type="checkbox" name="closingConfirmed"> J’ai vérifié les soldes et les opérations en attente.</label><div class="form-error banner warning hidden" role="alert"></div></form>`,`<button class="btn secondary" data-action="close-dialog">Annuler</button><button class="btn primary" data-action="save-closing">Valider la clôture ${icon('check')}</button>`,'closing');}
function saveClosing(){if(writesBlocked())return;const m=current(),values={closingCA:fieldValue('closingCA'),closingR:fieldValue('closingR'),savingsActual:fieldValue('savingsActual')};if(!dialog.querySelector('[name=closingConfirmed]').checked)return errorBox('Vérifie les soldes puis coche la confirmation.');const result=E.closeMonth(m,values);if(result.valid===false||result.errors?.length)return errorBox(result.errors.join(' '));m.closed=true;m.forecast=false;m.closing=values;m.closedAt=new Date().toISOString();const saved=commitMonth(m);if(!saved){render();return errorBox('La clôture n’est pas sauvegardée. Exporte les données avant de fermer la page.');}dialog.close();render();toast('Mois clôturé. Une bonne habitude de plus !');}
function showClosing(){const m=current();if(!m.closed)return;const c=calc(m),t=m.closing.closingCA+m.closing.closingR;const later=Object.values(state.months).some(o=>o.key>m.key&&o.prepared&&(!o.forecast||o.closed));openDialog(`Bilan · ${esc(monthName(m.key))}`,`<div class="details-table">${detailRow('Solde réel CA',m.closing.closingCA)}${detailRow('Solde réel Revolut',m.closing.closingR)}${detailRow('Tampon réel',t)}${detailRow('Variation depuis le début du mois',t-c.openingTotal)}${detailRow('Écart avec le tampon prévu',t-c.bufferEndPlan)}${detailRow('Solde réel du Livret A',m.closing.savingsActual)}</div><p class="help">${later?'Ce mois alimente un mois suivant déjà confirmé : sa clôture reste figée pour préserver les reports.':'Une correction est possible tant qu’aucun mois suivant n’a été confirmé.'}</p>`,`<button class="btn secondary" data-action="close-dialog">Fermer</button>${!later?'<button class="btn primary" data-action="reopen">Rouvrir ce mois</button>':''}`);}
function history(){const ms=Object.values(state.months).filter(m=>m.prepared).sort((a,b)=>b.key.localeCompare(a.key));openDialog('Mon historique',ms.length?`<p class="dialog-intro">Les budgets et les règles de chaque mois sont conservés.</p>${ms.map(m=>{const c=calc(getMonth(m.key));return `<button class="history-row" data-action="open-history" data-key="${m.key}"><div><strong>${esc(monthName(m.key))}</strong><span>${m.closed?'Clôturé':'En cours'} · Salaire ${eur(m.salary)}</span></div><div><strong>${eur(m.closed?m.closing.closingCA+m.closing.closingR:c.bufferEndPlan)}</strong><span>Tampon ${m.closed?'réel':'prévu'}</span></div>${icon('chevron')}</button>`;}).join('')}`:`<div class="empty-state">${icon('history')}<h3>Ton histoire commence ici.</h3><p>Prépare ton premier mois pour le retrouver dans cet espace.</p></div>`);}
function trophies(){const s=stats(),awards=[['first','Premier cap','Préparer son premier mois.','spark'],['closed','Mois bouclé','Clôturer son premier mois.','check'],['regular','Bonne habitude','Clôturer trois mois.','history'],['goal','Une belle marge','Atteindre son objectif tampon à la clôture.','shield']];openDialog('Chaque petit pas compte',`<div class="progress-header"><div class="level-badge">${icon('trophy')}</div><div><span class="mini-label">NIVEAU ${s.level}</span><h3>${levelName(s.level)}</h3><p class="muted">${s.xp} points gagnés</p></div></div><div class="progress"><div class="progress-fill" style="width:${s.progress/150*100}%"></div></div><p class="help">Encore ${150-s.progress} points jusqu’au niveau suivant.</p><div class="trophy-grid">${awards.map(([id,title,desc,ic])=>`<div class="trophy ${state.achievements[id]?'unlocked':''}"><div>${icon(ic)}</div><strong>${title}</strong><p>${desc}</p><span>${state.achievements[id]?'Débloqué':'À découvrir'}</span></div>`).join('')}</div><div class="info-note">${icon('leaf')} +30 points par mois préparé, +70 par clôture, +100 pour ton objectif atteint. Les modifications ne rapportent pas de points supplémentaires. Utiliser ton tampon ne te pénalise pas.</div>`);}
function moreMenu(){openDialog('À portée de main',`<div class="utility-menu"><button data-action="forecast">${icon('up')}<span>Prévisions sur les prochains mois</span>${icon('arrow')}</button><button data-action="history">${icon('history')}<span>Historique des mois</span>${icon('arrow')}</button><button data-action="trophies">${icon('trophy')}<span>Mes progrès</span><small>Niveau ${stats().level}</small></button><button data-action="settings">${icon('settings')}<span>Préférences & sauvegardes</span>${icon('arrow')}</button>${!demo?'<button data-action="demo">'+icon('spark')+'<span>Voir un exemple</span>'+icon('arrow')+'</button>':''}</div>`);}
function settings(){openDialog('Mes préférences',`<div class="form-section"><h3>Marge sur cet appareil</h3><p class="help" data-pwa-status>${esc(pwaStatusText())}</p><div class="settings-buttons"><button class="btn secondary" data-action="install-app">${icon('download')} Installer Marge</button><button class="btn text-btn" data-action="check-update">Vérifier les mises à jour</button></div></div><div class="form-section"><h3>Affichage</h3><div class="settings-row"><div><strong>Mode sombre</strong><p class="help">Un affichage plus doux en soirée.</p></div><button class="btn secondary" data-action="theme">${icon('moon')} ${state.settings.theme==='dark'?'Activé':'Désactivé'}</button></div></div><div class="form-section"><h3>Mes données</h3><p class="help">La sauvegarde est automatique sur cet appareil. Téléphone et ordinateur ont chacun leurs données : utilise l’export et l’import pour les transférer. Aucune connexion bancaire n’est effectuée.</p><div class="settings-buttons"><button class="btn secondary" data-action="export">${icon('download')} Exporter une sauvegarde</button><button class="btn secondary" data-action="import">Importer une sauvegarde</button></div><p class="help">${state.lastExport?'Dernier export : '+new Date(state.lastExport).toLocaleString('fr-FR'):'Pense à exporter après une clôture mensuelle.'}</p>${loadError?'<button class="btn secondary" data-action="export-raw">Exporter la sauvegarde illisible</button>':''}</div><div class="form-section"><h3>Découvrir l’application</h3><button class="btn secondary" data-action="${demo?'exit-demo':'demo'}">${icon('spark')} ${demo?'Quitter la démonstration':'Ouvrir une démonstration'}</button></div><div class="form-section"><h3>Repartir de zéro</h3><p class="help">Efface les mois et les réglages de cet appareil. Exporte tes données avant de continuer.</p><button class="btn danger" data-action="reset-confirm">Réinitialiser mes données</button></div><p class="help version-line">Marge · Version 2.3 · Points d’étape</p>`);}
function exportData(raw=false){if(loadError&&!demo&&!raw)return exportData(true);const content=raw?localStorage.getItem(KEY)||'':JSON.stringify({...state,lastExport:new Date().toISOString()},null,2);download(content,`Marge_${raw?'recuperation':today()}_${new Date().toISOString().slice(0,10)}.json`,'application/json');if(!raw){state.lastExport=new Date().toISOString();if(!storageConflict)persist();toast('Sauvegarde exportée. Garde ce fichier en lieu sûr.');}}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validateState(x){if(!x||x.version!==1||!x.settings||!Number.isFinite(x.settings.goal)||x.settings.goal<=0||x.settings.goal>1e9||!['light','dark'].includes(x.settings.theme)||!/^\d{4}-(0[1-9]|1[0-2])$/.test(x.selectedMonth)||!Array.isArray(x.plans)||!x.plans.length||!x.months||typeof x.months!=='object'||Array.isArray(x.months)||!x.achievements||typeof x.achievements!=='object')throw Error('Format de sauvegarde non reconnu.');if(x.incomePlan!==undefined)validateIncomePlan(x.incomePlan);if(x.plans.length>1200||Object.keys(x.months).length>1200)throw Error('Sauvegarde trop volumineuse.');for(const p of x.plans){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(p.from))throw Error('Date de budget invalide.');checkBudget(p.budget);const c=E.calculate({salary:0,openingCA:0,openingR:0,salaryIncluded:false,savingsOpening:0,budget:p.budget,rules:p.rules,useBuffer:false});if(c.errors.length)throw Error(c.errors.join(' '));}for(const [key,m] of Object.entries(x.months)){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(key)||m.key!==key||typeof m.prepared!=='boolean'||typeof m.closed!=='boolean'||!m.done||typeof m.done.r!=='boolean'||typeof m.done.savings!=='boolean')throw Error('Mois invalide dans la sauvegarde.');if(m.forecast!==undefined&&typeof m.forecast!=='boolean')throw Error('Prévision mensuelle invalide.');if(m.salaryReference!==undefined)validateIncomeEntry(m.salaryReference);if(m.carry!==undefined&&(!m.carry||typeof m.carry!=='object'||Array.isArray(m.carry)||typeof m.carry.buffer!=='boolean'||typeof m.carry.savings!=='boolean'))throw Error('Reports mensuels invalides.');if(m.executed!==undefined){if(!m.executed||typeof m.executed!=='object'||Array.isArray(m.executed)||!['r','savings'].every(id=>typeof m.executed[id]==='number'&&Number.isFinite(m.executed[id])&&Math.abs(m.executed[id])<=1e9&&Math.abs(m.executed[id]*100-Math.round(m.executed[id]*100))<1e-6)||m.executed.savings<0)throw Error('Historique des virements invalide.');}const checkpointErrors=E.validateCheckpoints(m);if(checkpointErrors.length)throw Error(checkpointErrors.join(' '));checkBudget(m.budget);const c=E.calculate(m);if(c.errors.length)throw Error(c.errors.join(' '));if(m.closed){if(!m.prepared||!m.closing)throw Error('Clôture invalide.');const r=E.closeMonth(m,m.closing);if(r.errors.length)throw Error(r.errors.join(' '));}}M.validateReports(x);}

function validateIncomeEntry(e){
  if(!e||typeof e!=='object'||Array.isArray(e)||!Number.isFinite(e.salary)||e.salary<0||e.salary>1e9||Math.abs(e.salary*100-Math.round(e.salary*100))>1e-6||!/^\d{4}-(0[1-9]|1[0-2])$/.test(e.sourcePayroll)||typeof e.estimated!=='boolean')throw Error('Salaire prévisionnel invalide.');
}
function validateIncomePlan(plan){
  if(!plan||typeof plan!=='object'||Array.isArray(plan)||Object.keys(plan).length>120)throw Error('Calendrier de salaires invalide.');
  for(const [key,e] of Object.entries(plan)){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(key))throw Error('Mois de salaire invalide.');validateIncomeEntry(e);const expected=moveMonth(e.sourcePayroll,1).slice(5);if(key.slice(5)!==expected)throw Error('Le budget doit suivre le mois de paie d’un mois.');}
}
function forecastView(){
  const keys=Object.keys(state.incomePlan||{}).sort(),resolved=M.projectionMonths(state),byKey=new Map(resolved.map(m=>[m.key,m]));
  return `<section class="forecast-intro"><p>Le salaire d’un mois finance le budget du mois suivant. Les projections suivent tes budgets, tes pourcentages et les reports du tampon et du Livret A.</p><button class="btn secondary" data-action="import">${icon('download')} Importer un calendrier de salaires</button></section>${keys.length?`<p class="help forecast-assumption">Les revenus estimés reprennent les nets payés de référence, primes et retenues comprises. Les budgets sont supposés entièrement dépensés. Un déficit réduit le tampon simulé ; ouvre le mois pour choisir comment le financer. Aucun intérêt ni dépense supplémentaire n’est ajouté.</p>${!resolved.some(m=>m.prepared&&!m.forecast)?`<div class="banner warning"><div><strong>Renseigne d’abord ton point de départ.</strong><p>Prépare ton mois actuel avec tes budgets, ton tampon et ton Livret A. Les projections suivantes se calculeront automatiquement.</p></div><button class="btn secondary small" data-action="forecast-start">Préparer mon point de départ</button></div>`:''}<div class="forecast-table"><div class="forecast-head"><span>Mois du budget</span><span class="forecast-income">Revenu net</span><span class="forecast-budget">Budget</span><span>Tampon fin</span><span>Livret A fin</span></div>${keys.map(k=>{const m=byKey.get(k)||getMonth(k),c=calc(m),ready=m.prepared&&(c.budgetTotal>0||m.budgetConfirmed),source=m.salaryReference||state.incomePlan[k],actual=state.months[k]?.prepared&&!state.months[k]?.forecast;return `<button class="forecast-row" data-action="open-history" data-key="${k}"><span><strong>${esc(monthName(k))}</strong><small>${actual?'Mois saisi':source.estimated?'Revenu estimé':'Paie connue'}<span class="mobile-income"> · ${eur(m.salary)}</span></small></span><span class="forecast-income">${eur(m.salary)}</span><span class="forecast-budget">${eur(c.budgetTotal)}</span><span class="${ready&&!c.funded?'text-danger':''}">${ready?eur(m.closed?m.closing.closingCA+m.closing.closingR:c.bufferEndPlan-c.shortfall):'—'}<small>${ready&&!c.funded?'Budget à équilibrer':''}</small></span><span>${ready?eur(m.closed?m.closing.savingsActual:c.savingsProjected):'—'}</span></button>`;}).join('')}</div><p class="help forecast-assumption">Ouvre un mois pour ajuster son budget ou remplacer l’estimation par le salaire reçu. Les salaires déjà confirmés restent prioritaires sur ce calendrier.</p>`:`<div class="empty-state">${icon('up')}<h3>Prévoir la suite, simplement.</h3><p>Importe ton calendrier de salaires pour voir évoluer ton tampon et ton épargne mois après mois.</p></div>`}`;
}
function showIncomeImport(data){
  if(dirty)throw Error('Enregistre ton budget avant d’importer les salaires.');
  if(data.version!==1)throw Error('Version de calendrier non reconnue.');validateIncomePlan(data.months);if(!Object.keys(data.months).length)throw Error('Le calendrier ne contient aucun salaire.');
  pendingImport=null;pendingIncomePlan=clone(data.months);const keys=Object.keys(data.months).sort();
  openDialog('Mes salaires prévisionnels',`<p class="dialog-intro">${keys.length} mois, de ${esc(monthName(keys[0]))} à ${esc(monthName(keys.at(-1)))}. Tes budgets, tes soldes et tes salaires déjà confirmés sont conservés.</p><div class="income-import-list">${keys.map(k=>`<div><span><strong>${esc(monthName(k))}</strong><small>Paie de ${esc(monthName(data.months[k].sourcePayroll))}${data.months[k].estimated?' · estimation':''}</small></span><strong>${eur(data.months[k].salary)}</strong></div>`).join('')}</div><div class="form-error banner warning hidden" role="alert"></div>`,`<button class="btn secondary" data-action="close-dialog">Annuler</button><button class="btn primary" data-action="confirm-income-import">Ajouter ces salaires ${icon('check')}</button>`);
}
function importIncomePlan(){
  if(writesBlocked()||!pendingIncomePlan)return;
  if(dirty)return errorBox('Enregistre ton budget avant d’importer les salaires.');
  const previous=state,candidate={...state,incomePlan:{...state.incomePlan,...pendingIncomePlan},months:{...state.months}};
  for(const [key,reference] of Object.entries(pendingIncomePlan)){
    const m=candidate.months[key];
    if(m?.forecast&&!m.closed)candidate.months[key]={...m,salary:reference.salary,salaryReference:clone(reference)};
  }
  try{validateState(candidate);}catch(e){return errorBox(e.message);}
  state=candidate;
  if(!persist()){state=previous;return errorBox('Le calendrier n’a pas pu être sauvegardé.');}
  pendingIncomePlan=null;dialog.close();page='forecast';render();toast('Salaires ajoutés. Les prévisions suivent tes budgets et tes reports.');
}

function checkBudget(b){if(!Array.isArray(b)||b.length>300)throw Error('Liste de dépenses invalide.');const ids=new Set();for(const r of b){if(typeof r.id!=='string'||!/^[A-Za-z0-9_-]{1,100}$/.test(r.id)||ids.has(r.id)||typeof r.name!=='string'||r.name.length>80||!['ca','r'].includes(r.account)||typeof r.enabled!=='boolean')throw Error('Dépense invalide.');ids.add(r.id);}}
let pendingImport=null,pendingIncomePlan=null;
$('#import-file').addEventListener('change',async ev=>{const file=ev.target.files[0];ev.target.value='';if(!file)return;if(file.size>5e6)return toast('Le fichier dépasse la limite de 5 Mo.',true);try{const parsed=JSON.parse(await file.text());if(parsed.kind==='marge-income-plan'){showIncomeImport(parsed);return;}pendingImport=parsed;validateState(pendingImport);openDialog('Remplacer mes données ?',`<p>Cette sauvegarde contient <strong>${Object.keys(pendingImport.months).length} mois</strong>. Elle remplacera les données actuelles de cet appareil.</p><p class="help">Exporte d’abord tes données actuelles si tu souhaites les conserver.</p>`,`<button class="btn secondary" data-action="export">Exporter avant remplacement</button><button class="btn primary" data-action="confirm-import">Importer ces données</button>`);}catch(e){pendingImport=null;toast(`Import refusé : ${e.message}`,true);}});
function startDemo(){if(dirty)return toast('Enregistre ton budget avant d’ouvrir la démonstration.',true);state=fresh();demo=true;state.selectedMonth=today();const b=blankBudget(),amounts=[950,180,120,250,55,350,195,100];b.forEach((x,i)=>x.amount=amounts[i]);state.plans[0].budget=clone(b);const m={...getMonth(),prepared:true,salary:3000,openingCA:450,openingR:150,savingsOpening:4800,budget:b};state.months[m.key]=m;state.achievements.first=true;draft=null;page='overview';dialog.close();render();}
function leaveDemo(){state=persistent;demo=false;draft=null;dirty=false;page='overview';dialog.close();render();}
function navigate(p){if(dirty&&p!==page)return toast('Enregistre les modifications du budget avant de changer de vue.',true);page=p;render();window.scrollTo({top:0,behavior:'instant'});}
function changeMonth(key){if(dirty)return toast('Enregistre le budget avant de changer de mois.',true);if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(key))return;state.selectedMonth=key;draft=null;if(!loadError&&!storageConflict)persist();dialog.close();render();}
const writeActions=new Set(['save-checkpoint','save-month','save-budget','save-closing','reopen','confirm-buffer','cancel-buffer','toggle-done','save-goal','theme','confirm-import','confirm-income-import','reset']);
async function action(name,el){if(writeActions.has(name)&&writesBlocked(name==='reset'||name==='confirm-import'))return;const m=current();switch(name){case'checkpoint':checkpointDialog();break;case'save-checkpoint':saveCheckpoint();break;case'more':moreMenu();break;case'forecast':dialog.close();navigate('forecast');break;case'confirm-income-import':importIncomePlan();break;case'forecast-start':changeMonth(today());navigate('overview');prepare();break;case'overview':navigate('overview');break;case'budget':navigate('budget');break;case'prev-month':changeMonth(moveMonth(state.selectedMonth,-1));break;case'next-month':changeMonth(moveMonth(state.selectedMonth,1));break;case'choose-month':openDialog('Choisir un mois',`<label class="field"><span>Mois à consulter</span><input id="month-choice" type="month" value="${state.selectedMonth}"></label>`,`<button class="btn primary" data-action="select-month">Afficher ce mois</button>`);break;case'select-month':changeMonth($('#month-choice').value);break;case'prepare':prepare();break;case'save-month':saveMonth();break;case'close-dialog':dialog.close();break;case'close-month':closeMonthDialog();break;case'save-closing':saveClosing();break;case'show-closing':showClosing();break;case'reopen':if(!Object.values(state.months).some(o=>o.key>m.key&&o.prepared&&(!o.forecast||o.closed))){m.closed=false;delete m.closing;commitMonth(m);dialog.close();render();toast('Mois rouvert. Tu peux corriger puis clôturer à nouveau.');}break;case'use-buffer':if(m.closed)return;openDialog('Utiliser une partie du tampon',`<p>Pour maintenir tes budgets, <strong>${eur(Math.min(calc(m).deficit,calc(m).bufferAvailable))}</strong> seront pris sur ta réserve.</p><p class="help">Le reste disponible sera affiché séparément. Aucun versement d’épargne ni bonus ne sera prévu pendant ce déficit.</p>`,`<button class="btn secondary" data-action="close-dialog">Annuler</button><button class="btn primary" data-action="confirm-buffer">Utiliser le tampon</button>`);break;case'confirm-buffer':m.useBuffer=true;m.done={r:false,savings:false};commitMonth(m);dialog.close();render();break;case'cancel-buffer':m.useBuffer=false;m.done={r:false,savings:false};commitMonth(m);render();break;case'toggle-done':if(!m.closed&&['r','savings'].includes(el.dataset.id)){const id=el.dataset.id,o=operation(m,id);m.executed={r:0,savings:0,...m.executed};m.executed[id]=o.complete?0:o.target;m.done[id]=!o.complete;commitMonth(m);render();}break;case'budget-ca':budgetAccount='ca';render();break;case'budget-r':budgetAccount='r';render();break;case'add-line':if(!m.closed){if(draft.budget.length>=300)return toast('Le budget contient déjà 300 postes.',true);draft.budget.push({id:uid(),account:el.dataset.account,name:'',category:'Autres',amount:0,enabled:true});dirty=true;render();const rows=app.querySelectorAll(`.budget-panel.${el.dataset.account} .name-input`);rows[rows.length-1]?.focus();}break;case'remove-line':if(!m.closed){draft.budget=draft.budget.filter(b=>b.id!==el.dataset.id);dirty=true;render();}break;case'preset':if(!m.closed){const sets={buffer:[70,0,30],balance:[60,20,20],available:[90,10,0]},[r,ca,t]=sets[el.dataset.id];Object.assign(draft.rules,{rPct:r,caPct:ca,tPct:t});dirty=true;render();const fold=app.querySelector('.rules-fold');if(fold)fold.open=true;}break;case'save-budget':saveBudget();break;case'goal':openDialog('Mon objectif tampon',`<p class="dialog-intro">Choisis la réserve avec laquelle tu te sentiras à l’aise. Tu peux la faire évoluer à tout moment.</p>${numberField('goal','Objectif à atteindre',state.settings.goal)}<div class="form-error banner warning hidden"></div>`,`<button class="btn primary" data-action="save-goal">Enregistrer mon objectif</button>`);break;case'save-goal':{const value=fieldValue('goal');if(!Number.isFinite(value)||value<=0||value>1e9||round(value)!==value)return errorBox('Indique un montant positif, avec deux décimales maximum.');state.settings.goal=value;award();persist();dialog.close();render();break;}case'history':history();break;case'open-history':changeMonth(el.dataset.key);navigate('overview');break;case'trophies':trophies();break;case'settings':settings();break;case'install-app':await installApp();break;case'check-update':await window.MargePWA?.checkForUpdates(true);refreshPWAStatus();break;case'theme':state.settings.theme=state.settings.theme==='dark'?'light':'dark';persist();render();settings();break;case'export':exportData();break;case'export-raw':exportData(true);break;case'import':$('#import-file').click();break;case'confirm-import':if(pendingImport){const previous={state,persistent,demo,loadError};state=pendingImport;demo=false;loadError=false;if(!persist()){state=previous.state;persistent=previous.persistent;demo=previous.demo;loadError=previous.loadError;render();return;}pendingImport=null;dirty=false;draft=null;page='overview';dialog.close();render();toast('Sauvegarde importée. Tes mois sont restaurés.');}break;case'demo':startDemo();break;case'exit-demo':leaveDemo();break;case'reset-confirm':openDialog('Réinitialiser cet appareil ?',`<p>Tous les mois, budgets et réglages seront supprimés de cet appareil.</p><label class="field"><span>Écris EFFACER pour confirmer</span><input id="reset-word" autocomplete="off" placeholder="EFFACER"></label>`,`<button class="btn secondary" data-action="close-dialog">Annuler</button><button class="btn danger" data-action="reset">Effacer les données</button>`);break;case'reset':if($('#reset-word').value!=='EFFACER')return toast('Écris EFFACER pour confirmer.',true);{const previous={state,persistent,loadError};state=fresh();loadError=false;if(!persist()){state=previous.state;persistent=previous.persistent;loadError=previous.loadError;render();return;}dirty=false;draft=null;page='overview';dialog.close();render();toast('Tu peux préparer ton premier mois.');}break;}}
for(const root of [app,dialog])root.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el)return;ev.preventDefault();action(el.dataset.action,el);});
app.addEventListener('input',ev=>{const el=ev.target;if(current().closed)return;if(el.dataset.budgetId){const b=draft.budget.find(b=>b.id===el.dataset.budgetId),p=el.dataset.prop;if(b){b[p]=p==='enabled'?el.checked:p==='amount'?num(el.value):el.value;refreshDraft();}}if(el.dataset.rule){draft.rules[el.dataset.rule]=num(el.value);app.querySelectorAll('.preset').forEach(p=>p.classList.remove('active'));refreshDraft();}});
dialog.addEventListener('input',ev=>{if(activeForm==='month')syncCarryFields(ev.target.name);if(activeForm==='closing'){const a=fieldValue('closingCA'),b=fieldValue('closingR');const el=$('#close-preview');if(el)el.textContent=`Nouveau tampon : ${Number.isFinite(a+b)?eur(a+b):'—'}`;}});
dialog.addEventListener('submit',e=>{e.preventDefault();if(activeForm==='month')saveMonth();if(activeForm==='checkpoint')saveCheckpoint();});
dialog.addEventListener('close',syncPWA);
window.addEventListener('marge:pwa-status',refreshPWAStatus);
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){storageConflict=true;if(!demo){render();toast('Les données ont changé dans un autre onglet. Cette page est en lecture seule jusqu’au rechargement.',true);}}});
render();
})();
